import { cardinalize } from './lib/cardinalize.mjs';
import { getProgramName, parseTest12Args, ParserExit } from './lib/cli-parser.mjs';
import { unitLen } from './lib/unit-len.mjs';

function writeLine(stream, value) {
  stream.write(`${value}\n`);
}

export function main(argv = process.argv.slice(2), stdout = process.stdout, stderr = process.stderr) {
  const programName = getProgramName(process.argv[1]);

  let args;
  try {
    args = parseTest12Args(argv, programName);
  } catch (error) {
    if (error instanceof ParserExit) {
      const stream = error.stream === 'stdout' ? stdout : stderr;
      stream.write(error.output);
      return error.status;
    }

    throw error;
  }

  const items = args.a.split(',');

  writeLine(stdout, unitLen(items, args.b));
  writeLine(stdout, cardinalize(args.b, items.length));
  writeLine(stdout, unitLen(items.slice(0, 3), args.b));
  writeLine(stdout, cardinalize(args.b, 1));
  writeLine(stdout, unitLen(items.slice(0, 1), args.b));

  return 0;
}

const exitCode = main();
if (exitCode !== 0) {
  process.exit(exitCode);
}

