    `usage: ${programName} [-h] --a A --b B\n\n` +
    'options:\n' +
    '  -h, --help  show this help message and exit\n' +
    '  --a A       Comma-separated items\n' +
    '  --b B       Unit name\n'
  );
}

function formatError(programName, message) {
  return `usage: ${programName} [-h] --a A --b B\n${programName}: error: ${message}\n`;
}

function isOptionLike(token) {
  return token.startsWith('-') && token !== '-';
}

function resolveHelp(token) {
  if (token.startsWith('--')) {
    if (token === '--') {
      return null;
    }

    const equalsIndex = token.indexOf('=');
    const optionToken = equalsIndex === -1 ? token : token.slice(0, equalsIndex);
    if (optionToken.length > 2 && '--help'.startsWith(optionToken)) {
      return {
        explicitArgument: equalsIndex === -1 ? null : token.slice(equalsIndex + 1),
      };
    }

    return null;
  }

  if (token.startsWith('-h=')) {
    return { explicitArgument: token.slice(3) };
  }

  if (token.startsWith('-h')) {
    return { explicitArgument: null };
  }

  return null;
}

function resolveOption(token) {
  if (token === '--a') {
    return { key: 'a', optionName: '--a', inlineValue: null };
  }

  if (token.startsWith('--a=')) {
    return { key: 'a', optionName: '--a', inlineValue: token.slice(4) };
  }

  if (token === '--b') {
    return { key: 'b', optionName: '--b', inlineValue: null };
  }

  if (token.startsWith('--b=')) {
    return { key: 'b', optionName: '--b', inlineValue: token.slice(4) };
  }

  return null;
}

export function parseTest12Args(argv, programName) {
  const values = {
    a: undefined,
    b: undefined,
  };
  const unknownTokens = [];

  for (let index = 0; index < argv.length; index += 1) {
    const token = argv[index];

    const helpMatch = resolveHelp(token);
    if (helpMatch) {
      if (helpMatch.explicitArgument !== null) {
        throw new ParserExit(
          2,
          formatError(
            programName,
            `argument -h/--help: ignored explicit argument '${helpMatch.explicitArgument}'`,
          ),
          'stderr',
        );
